using System.IO;using UnityEngine;using IslandGame;
public static class InspectApprovedTerrain {public static object Main(){var original=Resources.Load<GameObject>("NatureAuthoredMap").GetComponentInChildren<Terrain>(true).terrainData;var palette=Resources.Load<BattleDioramaSettings>("BattleDioramaSettings").groundPalette;bool same=original.heightmapResolution==palette.heightmapResolution&&original.size==palette.size;var a=original.GetHeights(0,0,original.heightmapResolution,original.heightmapResolution);var b=palette.GetHeights(0,0,palette.heightmapResolution,palette.heightmapResolution);if(same)for(int y=0;y<a.GetLength(0);y++)for(int x=0;x<a.GetLength(1);x++)if(a[y,x]!=b[y,x])same=false;var result=new{passed=same,heightSamples=a.Length,originalDetails=original.detailPrototypes.Length,paletteDetails=palette.detailPrototypes.Length,originalTrees=original.treeInstanceCount,paletteTrees=palette.treeInstanceCount,originalSize=original.size.ToString(),paletteSize=palette.size.ToString()};File.WriteAllText("C:/Users/SHK/island-contact-diorama-20261107/evidence/approved-terrain.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}}
